353	  }
354	  let process_environment = @env.get_env_vars()
355	  let secrets = [] + protected_secrets.unwrap_or([])
356	  if environment is Some(environment) {
357	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
358	      secrets.push(secret)
359	    }
360	  }
361	  if tunnel_directory is Some(directory) &&
362	    diagnostic_workspace_environments.get(directory) is Some(environment) {
363	    for secret in Progress::new("diagnostic-evidence", environment~).secrets {
364	      secrets.push(secret)
365	    }
366	  }
367	  if error_message is Some(message) {
368	    let message = diagnostic_text(
369	      message,
370	      environment=process_environment,
371	      protected_secrets=secrets,
372	    )
373	    set_field(event, "errorMessage", Json::string(message))
374	    set_field(
375	      event,
