377	      Json::boolean(
378	        details_truncated ||
379	        message.has_suffix("\n[error details incomplete or truncated]"),
380	      ),
381	    )
382	  }
383	  if tunnel_directory is Some(directory) {
384	    set_field(
385	      event,
386	      "tunnelDirectory",
387	      Json::string(
388	        diagnostic_text(
389	          directory,
390	          environment=process_environment,
391	          protected_secrets=secrets,
392	        ),
393	      ),
394	    )
395	  }
396	  for
397	    pair in [
398	      ("expectedWorkspaceUid", expected_workspace_uid),
399	      ("observedWorkspaceUid", observed_workspace_uid),
400	    ] {
401	    if pair.1 is Some(value) {
402	      set_field(
