410	          ),
411	        ),
412	      )
413	    }
414	  }
415	  let evidence_truncated : Ref[Bool] = { val: evidence_incomplete, }
416	  if source is Some(evidence) {
417	    let value = evidence.to_json()
418	    if value.stringify().length() <= 65536 {
419	      set_field(
420	        event,
421	        "source",
422	        diagnostic_json(
423	          value,
424	          process_environment,
425	          secrets,
426	          evidence_truncated,
427	          0,
428	          stable_activity=evidence_stable_activity,
429	        ),
430	      )
431	    } else {
432	      evidence_truncated.val = true
433	    }
434	  }
435	  if evidence is Some(value) {
436	    if value.stringify().length() <= 65536 {
437	      set_field(
438	        event,
439	        "evidence",
440	        diagnostic_json(
441	          value, process_environment, secrets, evidence_truncated, 0,
442	        ),
443	      )
444	    } else {
445	      evidence_truncated.val = true
446	    }
447	  }
448	  if evidence_truncated.val {
449	    set_field(event, "evidenceTruncated", Json::boolean(true))
450	    set_field(event, "completeness", Json::string("partial"))
451	  }
452	  if os_errno is Some(code) && code > 0 && code < 4096 {
453	    set_field(event, "osErrno", Json::number(code.to_double()))
454	  }
455	  if exit_code is Some(code) {
456	    set_field(event, "exitCode", Json::number(code.to_double()))
457	  }
458	  for pair in [("errorType", error_type), ("phase", phase)] {
459	    if pair.1 is Some(text) {
460	      set_field(event, pair.0, Json::string(text))
461	    }
462	  }
463	  if duration_ms is Some(value) {
464	    set_field(event, "durationMs", Json::number(value))
465	  }
466	  if attempt is Some(value) {
467	    set_field(event, "attempt", Json::number(value.to_double()))
468	  }
469	  if timeout_ms is Some(value) {
470	    set_field(event, "timeoutMs", Json::number(value.to_double()))
471	  }
472	  if retry_delay_ms is Some(value) {
473	    set_field(event, "retryDelayMs", Json::number(value.to_double()))
474	  }
475	  let failed = error_type is Some(_) ||
476	    ["failed", "timeout", "cancelled", "warning", "process-error"].contains(
477	      status,
478	    )
479	  if diagnostic_pending.length() >= 64 {
480	    let mut evict = -1
481	    if failed {
482	      for index in diagnostic_pending_inflight.val..<diagnostic_pending.length() {
483	        if !diagnostic_pending[index].failed {
484	          evict = index
485	          break
486	        }
487	      }
488	      if evict < 0 &&
489	        diagnostic_pending_inflight.val < diagnostic_pending.length() {
490	        evict = diagnostic_pending_inflight.val
491	      }
492	    }
493	    if evict < 0 {
494	      diagnostic_recording_failed("buffer_full", phase="buffer", event_time~)
495	      return
496	    }
497	    let removed = diagnostic_pending.remove(evict)
498	    diagnostic_pending.push({ event, failed, time: event_time, })
499	    diagnostic_recording_failed(
500	      "buffer_full",
501	      phase="buffer",
502	      event_time=removed.time,
503	    )
504	    try_flush_diagnostic_recording()
505	    return
506	  }
507	  diagnostic_pending.push({ event, failed, time: event_time, })
508	  try_flush_diagnostic_recording()
509	}
