 828	        matched += 1
 829	      }
 830	      prefixes[index] = matched
 831	    }
 832	    matched = 0
 833	    for index in 0..<boundary {
 834	      while matched > 0 && (matched == limit || value[matched] != chars[index]) {
 835	        matched = prefixes[matched - 1]
 836	      }
 837	      if matched < limit && value[matched] == chars[index] {
 838	        matched += 1
 839	      }
 840	    }
 841	    boundary -= matched
 842	  }
 843	  if boundary == chars.length() {
 844	    text
 845	  } else {
 846	    character_text(chars, 0, boundary) + "[redacted]"
 847	  }
 848	}
