 857	///|
 858	fn diagnostic_add_protected(
 859	  value : String,
 860	  output : String,
 861	  uncertain : Bool,
 862	  destination : Array[String],
 863	  result : DiagnosticProtectedValues,
 864	) -> Unit {
 865	  if value == "" ||
 866	    (
 867	      !output.contains(value) &&
 868	      (!uncertain || diagnostic_partial_secret(output, [value]) == output)
 869	    ) {
 870	    return
 871	  }
 872	  if result.secrets.length() >= 512 {
 873	    result.incomplete = true
 874	    return
 875	  }
 876	  destination.push(value)
 877	}
