 879	///|
 880	fn diagnostic_protected_values(
 881	  value : Json,
 882	  result : DiagnosticProtectedValues,
 883	  output : String,
 884	  uncertain : Bool,
 885	  secret~ : Bool = false,
 886	  depth~ : Int32 = 0,
 887	) -> Unit {
 888	  if result.visited >= 65536 || depth >= 64 {
 889	    result.incomplete = true
 890	    return
 891	  }
 892	  result.visited += 1
 893	  match value {
 894	    Json::String(text) if text != "" && secret => {
 895	      let destination = result.secrets
 896	      diagnostic_add_protected(text, output, uncertain, destination, result)
 897	      for line in text.split("\n") {
 898	        if line != "" && line.length() < text.length() {
 899	          diagnostic_add_protected(
 900	            line.to_owned(),
 901	            output,
 902	            uncertain,
 903	            destination,
 904	            result,
 905	          )
 906	        }
 907	        for word in line.split(" ") {
 908	          for part in word.split("=") {
 909	            if part != "" && part.length() < text.length() {
 910	              diagnostic_add_protected(
 911	                part.to_owned(),
 912	                output,
 913	                uncertain,
 914	                destination,
 915	                result,
 916	              )
 917	            }
 918	          }
 919	        }
 920	      }
 921	      let escaped = Json::string(text).stringify()
 922	      if escaped.length() > 2 {
 923	        let encoded = escaped[1:escaped.length() - 1].to_owned()
 924	        if encoded != text {
 925	          diagnostic_add_protected(
 926	            encoded, output, uncertain, destination, result,
 927	          )
 928	        }
 929	      }
 930	    }
 931	    Json::String(text) if text != "" => {
 932	      let mut next_secret = false
 933	      for word in text.split(" ") {
 934	        let word = word.to_owned()
 935	        if next_secret {
 936	          diagnostic_add_protected(
 937	            word,
 938	            output,
 939	            uncertain,
 940	            result.secrets,
 941	            result,
 942	          )
 943	          next_secret = false
 944	        } else if word.split_once("=") is Some((name, value)) {
 945	          if credential_field(name.to_owned()) {
 946	            diagnostic_add_protected(
 947	              value.to_owned(),
 948	              output,
 949	              uncertain,
 950	              result.secrets,
 951	              result,
 952	            )
 953	          }
 954	        } else if word.has_prefix("-") && credential_field(word) {
 955	          next_secret = true
 956	        }
 957	      }
 958	    }
 959	    Json::Array(values) =>
 960	      for item in values {
 961	        diagnostic_protected_values(
 962	          item,
 963	          result,
 964	          output,
 965	          uncertain,
 966	          secret~,
 967	          depth=depth + 1,
 968	        )
 969	      }
 970	    Json::Object(values) =>
 971	      for name, item in values {
 972	        let key = name.to_lower().replace_all(old="_", new="")
 973	        diagnostic_protected_values(
 974	          item,
 975	          result,
 976	          output,
 977	          uncertain,
 978	          secret=secret || credential_field(name) || key == "pairingcode",
 979	          depth=depth + 1,
 980	        )
 981	      }
 982	    _ => ()
 983	  }
 984	}
