 986	///|
 987	fn diagnostic_output(
 988	  output : Bytes,
 989	  environment : Map[String, String],
 990	  protected_input? : String,
 991	  protected_secrets? : Array[String],
 992	  omitted~ : Bool = false,
 993	) -> String? {
 994	  if output.length() == 0 {
 995	    return None
 996	  }
 997	  let limit = if output.length() > 8192 { 8192 } else { output.length() }
 998	  let incomplete = omitted || limit < output.length()
 999	  let text = @utf8.decode_lossy(output[:limit])
1000	  let safeguards : DiagnosticProtectedValues = {
1001	    secrets: [],
1002	    visited: 0,
1003	    incomplete: false,
1004	  }
1005	  if protected_input is Some(input) {
1006	    diagnostic_protected_values(
1007	      @json.parse(input),
1008	      safeguards,
1009	      text,
1010	      incomplete,
1011	    ) catch {
1012	      _ => safeguards.incomplete = true
1013	    }
1014	  }
1015	  if safeguards.incomplete {
1016	    return Some(
1017	      "Error output omitted because protected input could not be fully matched\n[error details incomplete or truncated]",
1018	    )
1019	  }
1020	  Some(
1021	    diagnostic_text(
1022	      text,
1023	      environment~,
1024	      omitted=incomplete,
1025	      protected_secrets=safeguards.secrets + protected_secrets.unwrap_or([]),
1026	      incomplete_final_line=incomplete && output[limit - 1] != b'\n',
1027	    ),
1028	  )
1029	}
