1049	///|
1050	async fn DiagnosticCapture::read(
1051	  self : DiagnosticCapture,
1052	  reader : @process.ReadFromProcess,
1053	) -> Unit {
1054	  try {
1055	    while reader.read_some(max_len=4096) is Some(chunk) {
1056	      let remaining = self.limit - self.output.length()
1057	      let count = if chunk.length() < remaining {
1058	        chunk.length()
1059	      } else {
1060	        remaining
1061	      }
1062	      if count > 0 {
1063	        self.output.write_bytes(chunk[:count])
1064	      }
1065	      if count < chunk.length() {
1066	        self.truncated = true
1067	      }
1068	    }
1069	  } catch {
1070	    error =>
1071	      if @async.is_being_cancelled() {
1072	        raise error
1073	      } else {
1074	        self.truncated = true
1075	      }
1076	  }
1077	  self.finished = true
1078	}
