726	fn diagnostic_error(
727	  error : Error,
728	  environment? : Map[String, String],
729	) -> String {
730	  let (message, omitted) = match error {
731	    AdapterError(detail) => (detail, false)
732	    InvalidConfig(detail) => (detail, false)
733	    @base64.Malformed(_) => ("Malformed base64 input; input omitted", true)
734	    @utf8.Malformed(_) => ("Malformed UTF-8 input; input omitted", true)
735	    @json.InvalidNumber(position, _) =>
736	      (
737	        "Invalid JSON number at line \{position.line}, column \{position.column}; value omitted",
738	        true,
739	      )
740	    _ => (error.to_string(), false)
741	  }
742	  diagnostic_text(message, environment?, omitted~)
