745	///|
746	fn diagnostic_text(
747	  message : String,
748	  environment? : Map[String, String],
749	  omitted~ : Bool = false,
750	  protected_secrets? : Array[String],
751	  incomplete_final_line~ : Bool = false,
752	) -> String {
753	  let progress = Progress::new("diagnostic-error", environment?)
754	  if protected_secrets is Some(values) {
755	    for value in values {
756	      if value != "" {
757	        progress.secrets.push(value)
758	        for line in value.split("\n") {
759	          if line.trim() != "" && line.length() < value.length() {
760	            progress.secrets.push(line.to_owned())
761	          }
762	        }
763	      }
764	    }
765	  }
766	  progress.secrets.sort_by((a, b) => b.length().compare(a.length()))
767	  let lines = []
768	  let mut incomplete = omitted
769	  let source_lines = message.split("\n").to_array()
770	  for index in 0..<source_lines.length() {
771	    let line = source_lines[index]
772	    if lines.length() == 32 {
773	      incomplete = true
774	      ignore(lines.remove(1))
775	    }
776	    let truncated = line.length() > 1024
777	    let bounded = if truncated {
778	      incomplete = true
779	      line[:1024].to_owned()
780	    } else {
781	      line.to_owned()
782	    }
783	    let bounded = if truncated ||
784	      (incomplete_final_line && index == source_lines.length() - 1) {
785	      diagnostic_partial_secret(bounded, progress.secrets)
786	    } else {
787	      bounded
788	    }
789	    match progress.safe_message(bounded) {
790	      Some(safe) => lines.push(safe)
791	      None => {
792	        incomplete = true
793	        lines.push("[unavailable]")
794	      }
795	    }
796	  }
797	  if (incomplete || progress.details_truncated) &&
798	    lines.last() != Some("[error details incomplete or truncated]") {
799	    lines.push("[error details incomplete or truncated]")
800	  }
801	  lines.join("\n")
802	}
