1183	fn process_error_type(output : String) -> String {
1184	  let text = output.to_lower()
1185	  if text.contains("out of memory") || text.contains("cannot allocate memory") {
1186	    "memory_exhausted"
1187	  } else if text.contains("no space left on device") {
1188	    "disk_exhausted"
1189	  } else if text.contains("address already in use") ||
1190	    text.contains("addrinuse") {
1191	    "address_in_use"
1192	  } else if text.contains("permission denied (publickey") ||
1193	    text.contains("authentication failed") {
1194	    "authentication_failed"
1195	  } else if text.contains("host key verification failed") {
1196	    "host_key_failed"
1197	  } else if text.contains("connection refused") {
1198	    "connection_refused"
1199	  } else if text.contains("connection timed out") ||
1200	    text.contains("operation timed out") {
1201	    "connection_timeout"
1202	  } else if text.contains("could not resolve hostname") {
1203	    "name_resolution"
1204	  } else if text.contains("controlsocket") || text.contains("control socket") {
1205	    "control_socket"
1206	  } else if text.contains("build_vm:") {
1207	    "vm_boot"
1208	  } else if text.contains("create microsandbox vm") && text.contains("network:") {
