1450	fn diagnostic_clone_strategy(args : Array[String]) -> (String, String) {
1451	  let mut strategy = "full"
1452	  let mut count = 0
1453	  let mut invalid = false
1454	  let mut index = 0
1455	  while index < args.length() {
1456	    let argument = args[index]
1457	    let value = if argument == "--git-clone-strategy" {
1458	      count += 1
1459	      index += 1
1460	      if index < args.length() {
1461	        Some(args[index])
1462	      } else {
1463	        None
1464	      }
1465	    } else if argument.has_prefix("--git-clone-strategy=") {
1466	      count += 1
1467	      Some(argument[21:].to_owned())
1468	    } else {
1469	      None
1470	    }
1471	    if count > 0 &&
1472	      (
1473	        argument == "--git-clone-strategy" ||
1474	        argument.has_prefix("--git-clone-strategy=")
1475	      ) {
1476	      match value {
