  1285	///|
  1286	fn diagnostic_value(value : String?, kind : DiagnosticValueKind) -> Json {
  1287	  match value {
  1288	    None => { "state": "unset" }
  1289	    Some("") => { "state": "empty" }
  1290	    Some(text) => {
  1291	      let valid = match kind {
  1292	        Commit => valid_commit(text)
  1293	        Workspace => valid_workspace_id(text)
  1294	        Identity => text.length() <= 128 && valid_context(text)
  1295	        RefName => diagnostic_ref(text)
  1296	      }
  1297	      let credential_form = text
  1298	        .split("/")
  1299	        .iter()
  1300	        .any(part => {
  1301	          [
  1302	            "ghp_", "gho_", "ghu_", "ghs_", "ghr_", "github_pat_", "glpat-", "sk-",
  1303	            "eyJ",
  1304	          ]
  1305	          .iter()
  1306	          .any(prefix => part.has_prefix(prefix))
  1307	        })
  1308	      if valid && !credential_form {
  1309	        { "state": "valid", "value": text }
  1310	      } else {
  1311	        { "state": "invalid" }
  1312	      }
  1313	    }
  1314	  }
  1315	}
