  1317	///|
  1318	// A recording grammar, never a replacement for checkout validation. Excludes
  1319	// URLs, credential forms, control characters and Git's invalid ref syntax.
  1320	fn diagnostic_ref(text : String) -> Bool {
  1321	  text.length() <= 1024 &&
  1322	  !text.has_prefix("-") &&
  1323	  !text.contains("..") &&
  1324	  text
  1325	  .split("/")
  1326	  .iter()
  1327	  .all(part => {
  1328	    part != "" &&
  1329	    !part.has_prefix(".") &&
  1330	    !part.has_suffix(".") &&
  1331	    !part.has_suffix(".lock")
  1332	  }) &&
  1333	  text
  1334	  .iter()
  1335	  .all(c => {
  1336	    (c >= 'a' && c <= 'z') ||
  1337	    (c >= 'A' && c <= 'Z') ||
  1338	    (c >= '0' && c <= '9') ||
  1339	    c == '/' ||
  1340	    c == '-' ||
  1341	    c == '_' ||
  1342	    c == '.'
  1343	  })
  1344	}
