171	fn terminal_text(text : String) -> String? {
172	  let output = @buffer.Buffer(size_hint=256)
173	  let mut state = 0
174	  for c in text.iter() {
175	    match state {
176	      0 =>
177	        if c == '\u001b' {
178	          state = 1
179	        } else if c.to_int() < 32 && c != '\t' {
180	          return None
181	        } else {
182	          output.write_char_utf8(c)
183	        }
184	      1 =>
185	        if c == '[' {
186	          state = 2
187	        } else if c == ']' {
188	          state = 3
189	        } else {
190	          return None
260	      self.stage,
261	      "diagnostics-truncated",
262	      error_type="phase_limit",
263	      evidence?=self.context,
264	      protected_secrets=self.secrets,
265	      recording=self.recording,
266	    )
267	  }
268	  let key = ["pipeline", "operationId", "phase", "step"]
269	    .map(name => field(event, name).unwrap_or(Json::null()).stringify())
270	    .join(":")
271	  if state == "started" {
272	    if self.operations.length() >= 256 {
273	      self.operations.clear()
274	    }
275	    self.operations.set(key, @env.now())
276	    progress_message(label + ": running…")
277	  } else {
278	    let duration = match field(event, "durationMs") {
279	      Some(Json::Number(value, ..)) if value >= 0 && value < 864000000 =>
280	        Some(seconds(value.to_uint64()))
281	      _ => self.operations.get(key).map(start => seconds(@env.now() - start))
282	    }
283	    self.operations.remove(key)
284	    let timing = duration.map(value => value + ", ").unwrap_or("") +
285	      "elapsed " +
286	      seconds(@env.now() - progress_started)
287	    progress_message(
288	      label +
289	      ": " +
290	      (if state == "succeeded" { "done" } else { state }) +
291	      " (" +
292	      timing +
293	      ")",
294	    )
295	  }
296	}
