299	fn classic_build_step(text : String) -> Bool {
300	  guard text.has_prefix("Step ") &&
301	    text[5:].split_once("/") is Some((step, rest)) &&
302	    rest.split_once(" ") is Some((total, detail)) else {
303	    return false
304	  }
305	  step.length() > 0 &&
306	  total.length() > 0 &&
307	  step.iter().all(c => c >= '0' && c <= '9') &&
308	  total.iter().all(c => c >= '0' && c <= '9') &&
309	  detail.trim().has_prefix(":")
310	}
