312	///|
313	async fn Progress::message(
314	  self : Progress,
315	  text : String,
316	  debug~ : Bool,
317	  warning~ : Bool,
318	  emit~ : Bool = true,
319	) -> Unit {
320	  for line in text.split("\n") {
321	    let text = line.trim().to_owned()
322	    if text == "" {
323	      continue
324	    }
325	    guard self.safe_message(text) is Some(safe) else {
326	      self.details_truncated = true
327	      continue
328	    }
329	    if !debug || warning {
330	      self.remember(safe, warning~)
331	    }
332	    if !emit {
333	      continue
334	    }
335	    if safe.has_prefix("#") {
336	      guard safe.split_once(" ") is Some((id, rest)) &&
337	        id.length() > 1 &&
338	        id[1:].iter().all(c => c >= '0' && c <= '9') else {
339	        continue
340	      }
341	      let detail = rest.trim().to_owned()
342	      guard detail.has_prefix("[") ||
343	        detail.has_prefix("DONE") ||
344	        detail.has_prefix("ERROR") ||
345	        detail.has_prefix("CACHED") else {
346	        continue
347	      }
348	      if detail.has_prefix("ERROR") && debug && !warning {
349	        self.remember(safe, warning=true)
350	      }
351	      if self.builds.get(id.to_owned()) == Some(detail) {
352	        continue
353	      }
354	      if self.builds.length() < 2048 || self.builds.contains(id.to_owned()) {
355	        self.builds.set(id.to_owned(), detail)
356	      }
357	      progress_message("Build " + id.to_owned() + ": " + detail)
358	    } else if classic_build_step(safe) {
359	      // Classic RUN output has no prefix. Only its own completion marker
360	      // ends this mode; phase events on another pipe can arrive ahead of it.
361	      self.classic_build = true
362	      progress_message("Build " + safe)
363	    } else if safe.has_prefix("Successfully built ") ||
364	      safe.has_prefix("Successfully tagged ") {
365	      self.classic_build = false
366	      progress_message("Build: " + safe)
367	    } else if self.classic_build && !warning {
368	      continue
369	    } else if !debug && !safe.has_prefix("{") && !safe.has_prefix("[") {
370	      progress_message(self.stage + ": " + safe)
371	    } else if !debug && safe.has_prefix("[credential") {
372	      progress_message(self.stage + ": " + safe)
373	    }
374	  }
375	}
