377	///|
378	async fn Progress::line(
379	  self : Progress,
380	  line : String,
381	  statuses~ : Bool,
382	  messages~ : Bool,
383	) -> Unit {
384	  if line.trim() == "" {
385	    return
386	  }
387	  let event = @json.parse(line) catch { _ => Json::null() }
388	  if field(event, "kind") == Some(Json::string("status")) {
389	    if field(event, "state") == Some(Json::string("failed")) &&
390	      field(event, "error") is Some(error) {
391	      for name in ["message", "hint"] {
392	        if field(error, name) is Some(Json::String(text)) {
393	          self.message(
394	            text,
395	            debug=false,
396	            warning=true,
397	            emit=messages || statuses,
398	          )
399	        }
400	      }
401	    }
402	    if statuses || messages {
403	      self.status(event)
404	    }
405	    return
406	  }
407	  // Result envelopes and arbitrary structured responses are never log text.
408	  if field(event, "kind") == Some(Json::string("result")) {
409	    return
410	  }
411	  if event is Json::Object(_) {
412	    let kind = field(event, "kind")
413	    guard kind == None ||
