507	///|
508	async fn Progress::read_output(
509	  self : Progress,
510	  reader : @process.ReadFromProcess,
511	  capture~ : Bool,
512	  statuses~ : Bool = false,
513	  messages~ : Bool = false,
514	  raw_messages~ : Bool = false,
515	) -> String {
516	  let output = @buffer.Buffer(size_hint=4096)
517	  let pending = @buffer.Buffer(size_hint=4096)
518	  let mut oversized = false
519	  let mut tail = ""
520	  while reader.read_some(max_len=4096) is Some(chunk) {
521	    if capture {
522	      output.write_bytes(chunk)
523	    } else {
524	      tail += @utf8.decode_lossy(chunk)
525	      if tail.length() > 8192 {
526	        tail = tail[tail.length() - 8192:].to_owned()
527	      }
528	    }
529	    for byte in chunk {
530	      if byte == b'\n' || byte == b'\r' {
531	        if !oversized && pending.length() > 0 {
532	          let line = @utf8.decode(pending.to_bytes()) catch {
533	            _ => {
534	              self.details_truncated = true
535	              ""
536	            }
537	          }
538	          if raw_messages {
539	            self.message(line, debug=false, warning=true, emit=false)
540	          } else if capture {
541	            self.line(line, statuses~, messages~)
542	          } else {
543	            self.stderr_line(line, statuses~, messages~)
544	          }
545	        }
546	        pending.reset()
547	        oversized = false
548	      } else if !oversized {
549	        if pending.length() == 65536 {
550	          pending.reset()
551	          oversized = true
552	          self.details_truncated = true
553	        } else {
554	          pending.write_byte(byte)
555	        }
556	      }
557	    }
558	  }
559	  if !oversized && pending.length() > 0 {
560	    let line = @utf8.decode(pending.to_bytes()) catch {
561	      _ => {
562	        self.details_truncated = true
563	        ""
564	      }
565	    }
566	    if raw_messages {
567	      self.message(line, debug=false, warning=true, emit=false)
568	    } else if capture {
569	      self.line(line, statuses~, messages~)
570	    } else {
571	      self.stderr_line(line, statuses~, messages~)
572	    }
573	  }
574	  if capture {
575	    @utf8.decode(output.to_bytes())
576	  } else {
577	    tail
578	  }
579	}

