268	///|
269	fn Progress::safe_message(self : Progress, text : String) -> String? {
270	  guard terminal_text(text) is Some(text) else { return None }
271	  let lower = text.to_lower()
272	  if lower.contains("-----begin ") && lower.contains("private key-----") {
273	    self.private_key = REDACTED ")
274	    return Some("[private key redacted]")
275	  }
276	  if self.private_key {
277	    if lower.contains("-----end ") && lower.contains("private key-----") {
278	      self.private_key = false
279	    }
280	    return None
281	  }
282	  let mut safe = redact_known_values(redact_credentials(text), self.secrets)
283	  if safe.length() > 1024 {
284	    safe = safe[:1024].to_owned() + "… [truncated]"
285	    self.details_truncated = true
286	  }
287	  Some(safe)
288	}
