290	///|
291	fn redact_known_values(text : String, secrets : Array[String]) -> String {
292	  let chars = text.iter().to_array()
293	  let values : Array[Array[Char]] = []
294	  for secret in secrets {
295	    if secret.length() <= text.length() {
296	      values.push(secret.iter().to_array())
297	    }
298	  }
299	  let result = @buffer.Buffer(size_hint=text.length())
300	  let mut i = 0
301	  while i < chars.length() {
302	    if i + 10 <= chars.length() &&
303	      character_text(chars, i, i + 10) == "[redacted]" {
304	      result.write_string_utf8("[redacted]")
305	      i += 10
306	      continue
307	    }
308	    let mut matched = 0
309	    for index in 0..<values.length() {
310	      let value = values[index]
311	      let mut matches = value.length() > 0 &&
312	        i + value.length() <= chars.length()
313	      if matches {
314	        for j in 0..<value.length() {
315	          if chars[i + j] != value[j] {
316	            matches = false
317	            break
318	          }
319	        }
320	      }
321	      if matches {
322	        matched = value.length()
323	        break
324	      }
325	    }
326	    if matched > 0 {
327	      result.write_string_utf8("[redacted]")
328	      i += matched
329	    } else {
330	      result.write_char_utf8(chars[i])
331	      i += 1
332	    }
333	  }
334	  @utf8.decode_lossy(result.to_bytes())
335	}

