 29	      let auth = codex_credentials(home, recording=operation_recording(state))
 30	      let access = auth.access
 31	      let payload : Json = {
 32	        "auth_mode": "chatgptAuthTokens",
 33	        "tokens": {
 34	          "id_token": access,
 35	          "access_token": access,
 36	          "refresh_token": "",
 37	          "account_id": auth.account,
 38	        },
 39	        "last_refresh": codex_timestamp(@env.now()),
 40	      }
 41	      let script =
 42	        #|set -eu
