 45	        #|if test -f "$home/config.toml"; then
 46	        #|  ! grep -Eq '^[[:space:]]*cli_auth_credentials_store[[:space:]]*=[[:space:]]*"(auto|keyring)"' "$home/config.toml" || { printf '%s\n' 'Codex credential store is not file based' >&2; exit 1; }
 47	        #|fi
