317	        phase~,
318	        error_type=if error is AdapterError(_) {
319	          "settings_source"
320	        } else {
321	          "settings_transfer"
322	        },
323	        error_message=detail,
324	        recording=operation_recording(state),
325	      )
326	      raise error
327	    }
328	  }
329	  save_diagnostic(
330	    "orca-settings",
