286	///|
287	async fn refresh_codex(home : String, secrets : Array[String]) -> Unit {
288	  let (reader, output) = @process.read_from_process()
289	  defer reader.close()
290	  let (input, writer) = @process.write_to_process()
291	  defer writer.close()
292	  let (errors, stderr) = @process.read_from_process()
293	  defer errors.close()
294	  let captured = @buffer.Buffer(size_hint=1024)
295	  let incomplete : Ref[Bool] = { val: false, }
296	  let finished : Ref[Bool] = { val: false, }
297	  let failure = try {
298	    @async.with_task_group(async fn(group) {
299	      ignore(
300	        @process.spawn(
301	          group,
302	          "codex",
303	          ["app-server", "--stdio"],
304	          extra_env={ "CODEX_HOME": home },
305	          stdin=input,
306	          stdout=output,
307	          stderr~,
308	          no_wait=true,
309	        ),
310	      )
311	      group.spawn_bg(no_wait=true, async fn() {
312	        while errors.read_some(max_len=4096) is Some(chunk) {
313	          let remaining = 8192 - captured.length()
314	          let count = if chunk.length() < remaining {
315	            chunk.length()
316	          } else {
317	            remaining
318	          }
319	          if count > 0 {
320	            captured.write_bytes(chunk[:count])
321	          }
322	          if count < chunk.length() {
323	            incomplete.val = true
324	          }
325	        }
326	        finished.val = true
327	      })
328	      let initialize : Json = {
329	        "id": 1,
330	        "method": "initialize",
331	        "params": {
332	          "clientInfo": { "name": "orca-env-devsy", "version": version },
333	        },
334	      }
335	      writer.write(initialize.stringify() + "\n")
336	      codex_rpc_response(reader, 1, secrets)
337	      writer.write("{\"method\":\"initialized\"}\n")
338	      writer.write(
339	        "{\"id\":2,\"method\":\"account/read\",\"params\":{\"refreshToken\":true}}\n",
340	      )
341	      codex_rpc_response(reader, 2, secrets)
342	    })
343	    None
344	  } catch {
345	    error => Some(error)
346	  }
347	  if failure is Some(error) {
348	    if @async.is_being_cancelled() {
349	      raise error
350	    }
351	    let protected_input : Json = { "access_token": secrets }
352	    let detail = diagnostic_output(
353	      captured.to_bytes(),
354	      @env.get_env_vars(),
355	      protected_input=protected_input.stringify(),
356	      omitted=incomplete.val || !finished.val,
357	    )
358	    raise AdapterError(
359	      diagnostic_error(error) +
360	      detail
361	      .map(value => "\nCodex app-server stderr: " + value)
362	      .unwrap_or(
363	        if finished.val {
364	          ""
365	        } else {
366	          "\n[Codex app-server stderr incomplete]"
367	        },
368	      ),
369	    )
370	  }
371	}
