374	async fn codex_credentials(home : String, recording~ : Bool) -> CodexAuth {
375	  let initial = read_codex_auth(home)
376	  if initial.expiry - @env.now().to_double() / 1000 >= 604800 {
377	    return initial
378	  }
379	  let lock = @fs.open(
380	    home + "/.orca-env-devsy-refresh.lock",
381	    mode=ReadWrite,
382	    create_mode=OpenOrCreate,
383	    permission=0o600,
384	  )
385	  defer lock.close()
386	  while !lock.try_lock(Exclusive) {
387	    @async.sleep(100)
388	  }
389	  let before = read_codex_auth(home)
390	  if before.expiry - @env.now().to_double() / 1000 >= 604800 {
391	    return before
392	  }
393	  let mut phase = "refresh"
394	  try {
395	    refresh_codex(home, before.secrets)
396	    phase = "verify"
397	    let after = read_codex_auth(home)
398	    guard after.access != before.access && after.expiry > before.expiry else {
399	      raise AdapterError("Codex refresh not persisted")
400	    }
401	    save_diagnostic("codex-refresh", "success", recording~)
402	  } catch {
403	    error => {
404	      progress_write(
405	        "orca-env-devsy: warning: Codex refresh failed; checking remaining token lifetime\n",
406	      )
407	      let detail = diagnostic_error(error)
408	      save_diagnostic(
409	        "codex-refresh",
410	        "warning",
411	        phase~,
412	        error_type=if error is @async.TimeoutError {
413	          "timeout"
414	        } else {
415	          "refresh_failed"
416	        },
417	        error_message=detail,
418	        recording~,
419	      )
420	    }
421	  }
422	  let current = read_codex_auth(home)
423	  guard current.expiry > @env.now().to_double() / 1000 else {
424	    raise AdapterError("Expired access token")
425	  }
426	  if current.expiry - @env.now().to_double() / 1000 < 604800 {
427	    progress_write(
428	      "orca-env-devsy: warning: Codex token has less than seven days remaining\n",
429	    )
430	  }
 90	  env.set("ELECTRON_RUN_AS_NODE", "1")
 91	  env.remove("NODE_OPTIONS")
 92	  env.remove("NODE_REPL_EXTERNAL_MODULE")
 93	  settings_process(
 94	    executable,
 95	    ["-e", orca_settings_script(), "--", "export", resources, user_data],
 96	    environment=env,
 97	  )
 98	}
