132	    }
133	    writer.close()
134	    let (status, stdout, stdout_truncated, stderr, stderr_truncated) = if write_error
135	      is Some(error) {
136	      @async.with_timeout(1000, async fn() { output.wait() }) catch {
137	        wait_error => {
138	          if @async.is_being_cancelled() {
139	            raise wait_error
140	          }
141	          raise AdapterError(
142	            "Orca settings input transfer failed; process exit unavailable: " +
143	            diagnostic_error(error, environment~),
144	          )
145	        }
146	      }
147	    } else {
148	      output.wait()
149	    }
150	    guard status == 0 else {
151	      let mut phase = "process"
152	      let mut code = "process_exit"
153	      let mut detail = diagnostic_output(
154	        stderr,
155	        environment,
156	        protected_input?=input,
157	        omitted=stderr_truncated,
158	      )
159	      if !stderr_truncated {
160	        try {
161	          let error = @json.parse(@utf8.decode(stderr))
162	          let reported_phase = required(error, "phase")
163	          let reported_code = required(error, "code")
164	          if [
165	              "load", "read", "normalize", "input", "profile", "write", "verify",
166	            ].contains(reported_phase) &&
167	            ["EACCES", "ENOENT", "EBUSY", "ENOSPC", "INCOMPATIBLE", "INVALID"].contains(
168	              reported_code,
169	            ) {
170	            phase = reported_phase
171	            code = reported_code
172	            let kind = match field(error, "kind") {
173	              Some(Json::String(value)) if [
174	                  "Error", "TypeError", "SyntaxError", "ReferenceError", "RangeError",
175	                  "AssertionError", "URIError",
176	                ].contains(value) => Some(value)
177	              _ => None
178	            }
179	            let native_code = match field(error, "nativeCode") {
180	              Some(Json::String(value)) if value.length() > 0 &&
181	                value.length() <= 64 &&
182	                value
183	                .iter()
184	                .all(c => {
185	                  (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
186	                }) => Some(value)
187	              _ => None
188	            }
189	            detail = if kind is Some(kind) {
190	              Some(
191	                kind +
192	                native_code.map(value => " (" + value + ")").unwrap_or(""),
193	              )
194	            } else {
195	              None
196	            }
197	            for
198	              name in (if native_code == Some("MODULE_NOT_FOUND") {
199	                ["target", "missing", "cause", "location", "message", "path"]
200	              } else {
201	                ["target", "cause", "location", "message", "path"]
202	              }) {
203	              if field(error, name) is Some(Json::String(value)) &&
204	                value.length() > 0 &&
205	                value.length() <= 1024 &&
206	                diagnostic_output(
207	                  @utf8.encode(value),
208	                  environment,
209	                  protected_input?=input,
210	                  omitted=field(error, "detailsTruncated") ==
211	                    Some(Json::boolean(true)) &&
212	                    (name == "message" || name == "path" || name == "missing"),
213	                )
214	                is Some(safe) {
215	                detail = Some(
216	                  detail.unwrap_or("Error") + " " + name + "=" + safe,
217	                )
218	              }
219	            }
220	            if field(error, "detailsTruncated") == Some(Json::boolean(true)) {
221	              detail = Some(
222	                detail.unwrap_or("Error") +
223	                "\n[error details incomplete or truncated]",
224	              )
225	            }
226	          }
227	        } catch {
228	          _ => ()
229	        }
230	      }
231	      if write_error is Some(error) {
232	        detail = Some(
233	          detail.unwrap_or("Process exited without readable stderr") +
234	          "\nInput transfer failed: " +
235	          diagnostic_error(error, environment~),
236	        )
237	      }
238	      raise SettingsProcessError(phase, code, status, detail)
239	    }
240	    if write_error is Some(error) {
241	      raise error
242	    }
243	    guard !stdout_truncated else {
244	      raise AdapterError("Orca settings result exceeds size limit")
245	    }
246	    @utf8.decode(stdout)
247	  })
248	}
