 240	///|
 241	fn workspace_environment(state : Json) -> Map[String, String] {
 242	  let environment = match field(state, "executionEnvironment") {
 243	    Some(Json::Object(values)) => {
 244	      let result : Map[String, String] = Map([])
 245	      for (name, value) in values {
 246	        if value is Json::String(value) {
 247	          result.set(name, value)
 248	        }
 249	      }
 250	      result
 251	    }
 252	    _ => @env.get_env_vars()
 253	  }
 254	  for name in location_variables {
 255	    match field(field(state, "devsyEnv").unwrap_or(Json::null()), name) {
 256	      Some(Json::String(value)) => environment.set(name, value)
 257	      _ => environment.remove(name)
 258	    }
 259	  }
 260	  environment
 261	}
 262	
 263	///|
 264	fn workspace_directory(state : Json) -> String? {
 265	  match field(state, "hostDirectory") {
 266	    Some(Json::String(value)) => Some(value)
 267	    _ => None
 268	  }
 269	}
