 271	///|
 272	async fn workspace_program(state : Json, program : String) -> String {
 273	  let cwd = workspace_directory(state).unwrap_or(
 274	    @env.current_dir().unwrap_or("/"),
 275	  )
 276	  if program.has_prefix("/") {
 277	    return program
 278	  }
 279	  if program.contains("/") {
 280	    return cwd + "/" + program
 281	  }
 282	  let path = field(field(state, "devsyEnv").unwrap_or(Json::null()), "PATH")
 283	  let path = match path {
 284	    Some(Json::String(value)) => value
 285	    _ => "/usr/bin:/bin"
 286	  }
 287	  let mut fallback = None
 288	  for directory in path.split(":") {
 289	    let directory = if directory.has_prefix("/") {
 290	      directory.to_owned()
 291	    } else {
 292	      cwd + "/" + directory.to_owned()
 293	    }
 294	    let candidate = directory + "/" + program
 295	    if fallback is None {
 296	      fallback = Some(candidate)
 297	    }
 298	    if transport_access(@utf8.encode(candidate + "\u0000"), 1) == 0 &&
 299	      @fs.kind(candidate) != @fs.FileKind::Directory {
 300	      return candidate
 301	    }
 302	  }
 303	  fallback.unwrap_or(cwd + "/" + program)
 304	}
